<?php
namespace Tests\Feature;
use App\Models\SalesRoute;
use App\Models\Branch;use App\Models\Business;use App\Models\Customer;use App\Models\InventoryStock;use App\Models\Payment;use App\Models\Product;use App\Models\Supplier;use App\Models\SupplierPayment;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class BusinessWorkflowTest extends TestCase{
 use RefreshDatabase;
 private function owner():array{$business=Business::create(['name'=>'Test Trading']);$branch=Branch::create(['business_id'=>$business->id,'name'=>'Main','code'=>'MAIN']);$user=User::create(['name'=>'Owner','email'=>'owner@example.test','password'=>'password','role'=>'owner','business_id'=>$business->id,'branch_id'=>$branch->id,'is_active'=>true]);Sanctum::actingAs($user);return compact('business','branch','user');}
 public function test_public_registration_creates_an_isolated_business_branch_and_owner():void{$response=$this->postJson('/api/v1/auth/register',['business_name'=>'New Dealer Ltd','branch_name'=>'Dhaka Main','name'=>'New Owner','email'=>'newowner@example.test','mobile'=>'01700000000','address'=>'Dhaka','password'=>'password','password_confirmation'=>'password','device_name'=>'Flutter test']);$response->assertCreated()->assertJsonPath('user.role','owner')->assertJsonPath('user.business.name','New Dealer Ltd')->assertJsonPath('user.branch.name','Dhaka Main')->assertJsonStructure(['token']);$business=Business::where('name','New Dealer Ltd')->firstOrFail();$this->assertDatabaseHas('branches',['business_id'=>$business->id,'name'=>'Dhaka Main','code'=>'HEAD']);$this->assertDatabaseHas('users',['email'=>'newowner@example.test','business_id'=>$business->id,'role'=>'owner','is_active'=>1]);}
 public function test_salesperson_only_sees_assigned_routes_and_cannot_open_reports():void{$ctx=$this->owner();$salesperson=User::create(['name'=>'Sales One','email'=>'sales@example.test','password'=>'password','role'=>'salesperson','business_id'=>$ctx['business']->id,'branch_id'=>$ctx['branch']->id,'is_active'=>true]);$other=User::create(['name'=>'Sales Two','email'=>'sales2@example.test','password'=>'password','role'=>'salesperson','business_id'=>$ctx['business']->id,'branch_id'=>$ctx['branch']->id,'is_active'=>true]);$assigned=SalesRoute::create(['business_id'=>$ctx['business']->id,'branch_id'=>$ctx['branch']->id,'salesperson_id'=>$salesperson->id,'route_date'=>today(),'name'=>'Assigned Route']);SalesRoute::create(['business_id'=>$ctx['business']->id,'branch_id'=>$ctx['branch']->id,'salesperson_id'=>$other->id,'route_date'=>today(),'name'=>'Other Route']);Sanctum::actingAs($salesperson);$this->getJson('/api/v1/field-sales/routes')->assertOk()->assertJsonCount(1,'data')->assertJsonPath('data.0.id',$assigned->id);$this->getJson('/api/v1/reports/dashboard')->assertForbidden();}
 public function test_invoice_updates_stock_due_cost_and_collection():void{$ctx=$this->owner();$product=Product::create(['business_id'=>$ctx['business']->id,'name'=>'Oil','sku'=>'OIL-1','purchase_price'=>80,'selling_price'=>100]);$stock=InventoryStock::create(['branch_id'=>$ctx['branch']->id,'product_id'=>$product->id,'quantity'=>10,'reorder_level'=>2]);$customer=Customer::create(['business_id'=>$ctx['business']->id,'branch_id'=>$ctx['branch']->id,'name'=>'Retailer','credit_limit'=>1000]);$response=$this->postJson('/api/v1/invoices',['branch_id'=>$ctx['branch']->id,'customer_id'=>$customer->id,'paid_amount'=>150,'payment_method'=>'cash','items'=>[['product_id'=>$product->id,'quantity'=>2]]]);$response->assertCreated()->assertJsonPath('data.grand_total','200.00');$this->assertEquals(8,(float)$stock->fresh()->quantity);$this->assertEquals(50,(float)$customer->fresh()->current_due);$this->assertDatabaseHas('payments',['customer_id'=>$customer->id,'amount'=>150]);$this->assertDatabaseHas('sales_invoice_items',['product_id'=>$product->id,'unit_cost'=>80]);$this->assertDatabaseHas('audit_logs',['event'=>'SalesInvoice.created','subject_id'=>$response->json('data.id')]);}
 public function test_user_cannot_access_another_business_branch():void{$ctx=$this->owner();$other=Business::create(['name'=>'Other']);$otherBranch=Branch::create(['business_id'=>$other->id,'name'=>'Other Branch']);$this->getJson('/api/v1/inventory/stocks?branch_id='.$otherBranch->id)->assertNotFound();}
 public function test_owner_can_create_a_branch_assigned_user():void{$ctx=$this->owner();$this->postJson('/api/v1/admin/users',['name'=>'Accountant','email'=>'accounts@example.test','password'=>'password','role'=>'accountant','branch_id'=>$ctx['branch']->id])->assertCreated()->assertJsonPath('data.role','accountant');$this->assertDatabaseHas('users',['email'=>'accounts@example.test','business_id'=>$ctx['business']->id,'is_active'=>1]);}
 public function test_branch_user_cannot_access_another_branch_in_same_business():void{$ctx=$this->owner();$other=Branch::create(['business_id'=>$ctx['business']->id,'name'=>'Second']);$ctx['user']->update(['role'=>'manager']);$this->getJson('/api/v1/inventory/stocks?branch_id='.$other->id)->assertForbidden();}
 public function test_receiving_purchase_updates_average_cost_stock_due_and_payment():void{$ctx=$this->owner();$product=Product::create(['business_id'=>$ctx['business']->id,'name'=>'Rice','sku'=>'RICE-1','purchase_price'=>80,'selling_price'=>120]);$stock=InventoryStock::create(['branch_id'=>$ctx['branch']->id,'product_id'=>$product->id,'quantity'=>10,'reorder_level'=>2]);$supplier=Supplier::create(['business_id'=>$ctx['business']->id,'branch_id'=>$ctx['branch']->id,'name'=>'Supplier','credit_limit'=>5000]);$invoice=$this->postJson('/api/v1/purchase-invoices',['branch_id'=>$ctx['branch']->id,'supplier_id'=>$supplier->id,'paid_amount'=>50,'items'=>[['product_id'=>$product->id,'quantity'=>10,'unit_cost'=>100]]])->assertCreated()->json('data');$this->postJson('/api/v1/purchase-invoices/'.$invoice['id'].'/receive')->assertOk()->assertJsonPath('data.status','received');$this->assertEquals(20,(float)$stock->fresh()->quantity);$this->assertEquals(90,(float)$product->fresh()->purchase_price);$this->assertEquals(950,(float)$supplier->fresh()->current_due);$this->assertEquals(50,(float)SupplierPayment::first()->amount);}
 public function test_notifications_are_generated_for_low_stock_and_overdue_due():void{$ctx=$this->owner();$product=Product::create(['business_id'=>$ctx['business']->id,'name'=>'Sugar','sku'=>'SUGAR-1','purchase_price'=>50,'selling_price'=>60]);InventoryStock::create(['branch_id'=>$ctx['branch']->id,'product_id'=>$product->id,'quantity'=>2,'reorder_level'=>5]);Customer::create(['business_id'=>$ctx['business']->id,'branch_id'=>$ctx['branch']->id,'name'=>'Overdue Shop','current_due'=>500,'due_since'=>now()->subDays(45)]);$response=$this->getJson('/api/v1/notifications')->assertOk();$this->assertCount(2,$response->json('data.data'));}
 public function test_sales_return_restores_stock_reduces_due_and_records_refund():void{$ctx=$this->owner();$product=Product::create(['business_id'=>$ctx['business']->id,'name'=>'Soap','sku'=>'SOAP-1','purchase_price'=>80,'selling_price'=>100]);$stock=InventoryStock::create(['branch_id'=>$ctx['branch']->id,'product_id'=>$product->id,'quantity'=>10,'reorder_level'=>2]);$customer=Customer::create(['business_id'=>$ctx['business']->id,'branch_id'=>$ctx['branch']->id,'name'=>'Retailer','credit_limit'=>1000]);$invoice=$this->postJson('/api/v1/invoices',['branch_id'=>$ctx['branch']->id,'customer_id'=>$customer->id,'paid_amount'=>150,'payment_method'=>'cash','items'=>[['product_id'=>$product->id,'quantity'=>2]]])->assertCreated()->json('data');$this->postJson('/api/v1/invoices/'.$invoice['id'].'/returns',['refund_method'=>'cash','items'=>[['product_id'=>$product->id,'quantity'=>1]]])->assertCreated()->assertJsonPath('data.refund_amount','50.00')->assertJsonPath('data.due_reduction','50.00');$this->assertEquals(9,(float)$stock->fresh()->quantity);$this->assertEquals(0,(float)$customer->fresh()->current_due);$report=$this->getJson('/api/v1/reports/dashboard')->assertOk();$this->assertEquals(100,(float)$report->json('data.sales'));$this->assertEquals(80,(float)$report->json('data.cogs'));$this->assertEquals(100,(float)$report->json('data.net_collections'));}
 public function test_invoice_receipt_and_report_documents_download_as_files():void{$ctx=$this->owner();$product=Product::create(['business_id'=>$ctx['business']->id,'name'=>'Tea','sku'=>'TEA-1','purchase_price'=>20,'selling_price'=>30]);InventoryStock::create(['branch_id'=>$ctx['branch']->id,'product_id'=>$product->id,'quantity'=>10,'reorder_level'=>2]);$customer=Customer::create(['business_id'=>$ctx['business']->id,'branch_id'=>$ctx['branch']->id,'name'=>'Tea Shop','credit_limit'=>1000]);$invoice=$this->postJson('/api/v1/invoices',['branch_id'=>$ctx['branch']->id,'customer_id'=>$customer->id,'paid_amount'=>30,'payment_method'=>'cash','items'=>[['product_id'=>$product->id,'quantity'=>1]]])->assertCreated()->json('data');$this->get('/api/v1/invoices/'.$invoice['id'].'/pdf')->assertOk()->assertHeader('content-type','application/pdf');$payment=Payment::firstOrFail();$this->get('/api/v1/payments/'.$payment->id.'/receipt')->assertOk()->assertHeader('content-type','application/pdf');$this->get('/api/v1/reports/export/pdf')->assertOk()->assertHeader('content-type','application/pdf');$this->get('/api/v1/reports/export/excel')->assertOk();}
 public function test_csv_import_creates_product_and_customer():void{$ctx=$this->owner();$products=UploadedFile::fake()->createWithContent('products.csv',"name,sku,selling_price,opening_stock,branch_code\nImported Oil,IMP-01,150,12,MAIN\n");$this->post('/api/v1/imports/products',['file'=>$products])->assertOk()->assertJsonPath('created',1);$this->assertDatabaseHas('products',['business_id'=>$ctx['business']->id,'sku'=>'IMP-01']);$customers=UploadedFile::fake()->createWithContent('customers.csv',"name,mobile,credit_limit,branch_code\nImported Shop,01711111111,5000,MAIN\n");$this->post('/api/v1/imports/customers',['file'=>$customers])->assertOk()->assertJsonPath('created',1);$this->assertDatabaseHas('customers',['business_id'=>$ctx['business']->id,'mobile'=>'01711111111']);}
}
